def sourceIntervalCompletion (ν : Measure BridgeNoise) (a y T z : ℝ) : ℝ :=
  if 0 < T then intervalCompletion ν a y T z
  else if T = 0 ∧ y = z ∧ |y| < a then 1 else 0

def sourceRemainder (ν : Measure BridgeNoise) (a y T z b : ℝ) : ℝ :=
  sourceIntervalCompletion ν a (y + b) (T - b ^ 2) z - sourceIntervalCompletion ν a y T z -
    (b - b ^ 2 * (z - y) / T) * deriv (fun w => sourceIntervalCompletion ν a w T z) y

def upperOvershoot (ν : Measure BridgeNoise) (a y T z b : ℝ) : ℝ :=
  projectionOvershoot b (a - y) T (z - y)
    (deriv (fun w => sourceIntervalCompletion ν a w T z) y)

def lowerOvershoot (ν : Measure BridgeNoise) (a y T z b : ℝ) : ℝ :=
  projectionOvershoot (-b) (a + y) T (y - z)
    (-deriv (fun w => sourceIntervalCompletion ν a w T z) y)

def retainedRemainder (ν : Measure BridgeNoise) (a y T z b : ℝ) : ℝ :=
  if b ^ 2 ≤ T / 2 ∧ ¬ |y + b| < a then
    if a ≤ y + b then sourceRemainder ν a y T z (a - y)
    else sourceRemainder ν a y T z (-a - y)
  else sourceRemainder ν a y T z b

def pinPath (f : C(BridgeTime, ℝ)) : BridgeNoise :=
  ⟨f - f 0 • leftWeight - f 1 • rightWeight,
    by constructor <;> simp [leftWeight, rightWeight]⟩

def bridgePath (y T z : ℝ) (g : BridgeNoise) : C(BridgeTime, ℝ) :=
  ⟨fun t => (1 - (t : ℝ)) * y + (t : ℝ) * z + Real.sqrt T * g.val t,
    by fun_prop⟩
